from pqattest import (
    OneTimeSigner, WOTSOneTimeSigner, restore_ots_pair,
    auth_state_wrap, keygen, wots_keygen,
)

key = b'shared-secret'
lamport = OneTimeSigner(keygen()[0])
wots = WOTSOneTimeSigner(wots_keygen()[0])
generation = 7
blob_l = auth_state_wrap(lamport.checkpoint(), scheme='lamport', key=key, generation=generation)
blob_w = auth_state_wrap(wots.checkpoint(), scheme='wots', key=key, generation=generation)

state = {'high_water': 6}
def claim(token):
    if isinstance(token[0], tuple):
        gl = token[0][1]
        gw = token[1][1]
        if gl != gw or gl <= state['high_water']:
            return False
        state['high_water'] = gl
    else:
        if token[1] <= state['high_water']:
            return False
        state['high_water'] = token[1]
    return True

(l, w), g = restore_ots_pair(blob_l, blob_w, key=key, floor=state['high_water'], claim=claim)
assert g == 7
try:
    restore_ots_pair(blob_l, blob_w, key=key, claim=claim)
    raise AssertionError('replay should fail')
except ValueError:
    pass

# single-item path
state2 = {'high_water': 0}
def claim2(token):
    if token[1] <= state2['high_water']:
        return False
    state2['high_water'] = token[1]
    return True
r, gg = OneTimeSigner.from_auth_state(blob_l, key=key, min_generation=1, claim=claim2)
assert gg == 7
print('README example OK')
"

